"// Query Memory via SSH
function queryTvMemory() {
  const meminfo = execSsh('cat /proc/meminfo');
  let memTotal = 0;
  let memFree = 0;
  let memAvailable = 0;

  meminfo.split('\n').forEach(line => {
    if (line.startsWith('MemTotal:')) memTotal = parseInt(line.split(/\s+/)[1], 10) / 1024;
    if (line.startsWith('MemFree:')) memFree = parseInt(line.split(/\s+/)[1], 10) / 1024;
    if (line.startsWith('MemAvailable:')) memAvailable = parseInt(line.split(/\s+/)[1], 10) / 1024;
  });

  // Query WAM renderer process via ps aux
  const psWam = execSsh("ps aux | grep -E 'WebAppMgr.*renderer.*webos-pwa' | grep -v grep || true");
  let wamRendererPid = null;
  let wamRendererRssMb = 0;

  const wamLines = psWam.trim().split('\n').filter(Boolean);
  if (wamLines.length > 0) {
    const parts = wamLines[0].trim().split(/\s+/);
    wamRendererPid = parts[1];
    wamRendererRssMb = (parseInt(parts[5], 10) / 1024) || 0;
  }

  // Query service process via ps aux
  let servicePid = null;
  let serviceRssMb = 0;
  try {
    const psSvc = execSsh("ps aux | grep 'com.cinejoy.tv.service' | grep -v grep || true");
    const svcLines = psSvc.trim().split('\n').filter(Boolean);
    if (svcLines.length > 0) {
      const parts = svcLines[0].trim().split(/\s+/);
      servicePid = parts[1];
      serviceRssMb = (parseInt(parts[5], 10) / 1024) || 0;
    }
  } catch (_) {}

  return {
    memTotalMb: parseFloat(memTotal.toFixed(2)),
    memFreeMb: parseFloat(memFree.toFixed(2)),
    memAvailableMb: parseFloat(memAvailable.toFixed(2)),
    wamRendererPid,
    wamRendererRssMb: parseFloat(wamRendererRssMb.toFixed(2)),
    servicePid,
    serviceRssMb: parseFloat(serviceRssMb.toFixed(2))
  };
}"

