"// Query Memory via SSH
function queryTvMemory() {
  const meminfo = execSsh('cat /proc/meminfo');
  let memTotal = 0;
  let memFree = 0;
  let memAvailable = 0;

  meminfo.split('\n').forEach(line => {
    if (line.startsWith('MemTotal:')) memTotal = parseInt(line.split(/\s+/)[1], 10) / 1024;
    if (line.startsWith('MemFree:')) memFree = parseInt(line.split(/\s+/)[1], 10) / 1024;
    if (line.startsWith('MemAvailable:')) memAvailable = parseInt(line.split(/\s+/)[1], 10) / 1024;
  });

  // Query WAM renderer process
  const psOut = execSsh("ps -o pid,user,comm,rss,args -A | grep -E 'WebAppMgr.*renderer.*client-id' | grep -v grep || true");
  let wamRendererPid = null;
  let wamRendererRssMb = 0;

  const wamMatch = psOut.trim().split('\n').filter(Boolean);
  if (wamMatch.length > 0) {
    const parts = wamMatch[0].trim().split(/\s+/);
    wamRendererPid = parts[0];
    wamRendererRssMb = (parseInt(parts[3], 10) / 1024) || 0;
  }

  // Query service process
  let servicePid = null;
  let serviceRssMb = 0;
  try {
    const sOut = execSsh(`pidof ${CONFIG.serviceId} || true`);
    const p = sOut.match(/\b\d+\b/);
    if (p) {
      servicePid = p[0];
      const sStat = execSsh(`cat /proc/${servicePid}/status | grep -E 'VmRSS|VmHWM' || true`);
      sStat.split('\n').forEach(line => {
        if (line.startsWith('VmRSS:')) serviceRssMb = parseInt(line.split(/\s+/)[1], 10) / 1024;
      });
    }
  } catch (_) {}

  return {
    memTotalMb: parseFloat(memTotal.toFixed(2)),
    memFreeMb: parseFloat(memFree.toFixed(2)),
    memAvailableMb: parseFloat(memAvailable.toFixed(2)),
    wamRendererPid,
    wamRendererRssMb: parseFloat(wamRendererRssMb.toFixed(2)),
    servicePid,
    serviceRssMb: parseFloat(serviceRssMb.toFixed(2))
  };
}"

