"node -e "
(async () => {
  const r = await fetch('http://192.168.1.15:9998/json');
  const pages = await r.json();
  const target = pages.find(p => p.url && p.url.includes('com.cinejoy.tv'));
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise(res => ws.onopen = res);
  let id = 1;
  const send = (method, params) => new Promise(res => {
    const msgId = id++;
    const handler = (evt) => {
      const m = JSON.parse(evt.data);
      if (m.id === msgId) {
        ws.removeEventListener('message', handler);
        res(m.result);
      }
    };
    ws.addEventListener('message', handler);
    ws.send(JSON.stringify({ id: msgId, method, params }));
  });
  const res = await send('Runtime.evaluate', {
    expression: '(() => { const v = document.getElementById(\"main-video-player\"); return { readyState: v.readyState, paused: v.paused, currentTime: v.currentTime, buffered: v.buffered.length > 0 ? v.buffered.end(v.buffered.length - 1) : 0 }; })()',
    returnByValue: true
  });
  console.log('Video status now:', res.result.value);
  ws.close();
})();
""

